import re
import os
import base64
import numpy as np

np.set_printoptions(threshold=20, edgeitems=3)

infile = '/home/ctfplayer/ctf_files/server_output.txt'
labels = ['A', 'B', 'u', 'c']
results = {}

with open(infile, 'r') as f:
    data = f.read()

# Regex for blocks (A/B): <label>: '<shape>;<base64 or similar data>\n...'
for label in labels:
    # Match using re.DOTALL so newlines within base64 block don't break parse
    if label in ['u', 'c']:
        m = re.search(rf"^{label}: '(\d+);([A-Za-z0-9+/=\\n]+)'", data, re.MULTILINE)
    else:
        m = re.search(rf"^{label}: '([\d,]+);([A-Za-z0-9+/=\\n]+)'", data, re.MULTILINE)
    if not m:
        continue
    if label in ['u', 'c']:
        shape_str, b64 = m.groups()
        shape = (int(shape_str),)
    else:
        shape_str, b64 = m.groups()
        shape = tuple(map(int, shape_str.split(',')))
    b64 = b64.replace('\n', '')
    try:
        raw = base64.b64decode(b64)
    except Exception as e:
        raise Exception(f"Failed to decode {label}: {e}")
    # Heuristically determine dtype: probably uint8 or bool
    size = np.prod(shape)
    if len(raw) == size:
        dtype = np.uint8
    elif len(raw) == (size + 7) // 8:
        dtype = np.packbits
    else:
        # try for uint16, int64, etc as a guess
        for t in [np.uint16, np.int64, np.int32]:
            if len(raw) == size * np.dtype(t).itemsize:
                dtype = t
                break
        else:
            dtype = np.uint8  # fallback
    # Actually decode
    if dtype == np.packbits:
        arr = np.unpackbits(np.frombuffer(raw, dtype=np.uint8))[:size].reshape(shape)
        true_dtype = 'bool'
    else:
        arr = np.frombuffer(raw, dtype=dtype).reshape(shape)
        true_dtype = str(arr.dtype)
    # Save
    np.save(f'/home/ctfplayer/ctf_files/block_{label}.npy', arr)
    # Summary
    results[label] = {
        'shape': arr.shape,
        'dtype': true_dtype,
        'sample': arr.ravel()[:10].tolist(),
        'filename': f'block_{label}.npy',
    }

# Output summary
for label in labels:
    if label in results:
        meta = results[label]
        print(f"{label}: shape={meta['shape']}, dtype={meta['dtype']}, saved={meta['filename']}, sample={meta['sample']}")
